document.querySelectorAll('.sw2').forEach(item => {
  const row = item.querySelector('.sw2__row'), [flag, del] = item.querySelectorAll('.sw2__acts button');
  const setOpen = open => {
    item.classList.toggle('is-open', open);
    [flag, del].forEach(b => b.tabIndex = open ? 0 : -1);
  };
  let startX = null;
  row.addEventListener('pointerdown', e => { startX = e.clientX; });
  row.addEventListener('pointerup', e => {
    if (startX === null) return; const dx = e.clientX - startX; startX = null;
    if (dx < -40) setOpen(true); else if (dx > 40) setOpen(false);
  });
  row.addEventListener('pointercancel', () => { startX = null; });
  row.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') { e.preventDefault(); setOpen(true); flag.focus(); }
    else if (e.key === 'ArrowRight' || e.key === 'Escape') setOpen(false);
  });
  item.addEventListener('keydown', e => { if (e.key === 'Escape') { setOpen(false); row.focus(); } });
  flag.addEventListener('click', () => { flag.textContent = flag.textContent === 'Flag' ? 'Unflag' : 'Flag'; setOpen(false); row.focus(); });
  del.addEventListener('click', () => { item.classList.add('is-gone'); });
});
